package com.bank.contagion;

import java.util.ArrayDeque;
import java.util.Queue;
import java.util.logging.Logger;

// Spreads a compromise flag across a grid minute by minute (multi-source BFS).
public class ContagionSimulator {

    private static final Logger log = Logger.getLogger(ContagionSimulator.class.getName());

    // 0 = empty, 1 = clean account, 2 = compromised account
    public int minutesToSpread(int[][] grid) {
        int rows = grid.length, cols = grid[0].length;
        Queue<int[]> queue = new ArrayDeque<>();
        int fresh = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 2) queue.add(new int[]{r, c}); // sources
                else if (grid[r][c] == 1) fresh++;
            }
        }
        if (fresh == 0) { log.info("No clean accounts; minutes=0"); return 0; }

        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        int minutes = 0;
        while (!queue.isEmpty() && fresh > 0) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {      // one level = one minute
                int[] cell = queue.poll();
                for (int[] d : dirs) {
                    int nr = cell[0] + d[0], nc = cell[1] + d[1];
                    if (nr < 0 || nc < 0 || nr >= rows || nc >= cols) continue;
                    if (grid[nr][nc] == 1) {
                        grid[nr][nc] = 2;          // becomes compromised
                        fresh--;
                        queue.add(new int[]{nr, nc});
                    }
                }
            }
            minutes++;
        }
        int result = fresh == 0 ? minutes : -1;
        log.info("Fresh remaining=" + fresh + " -> minutes=" + result);
        return result;
    }
}
