package com.bank.contagion;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class ContagionDemo {

    private static final Logger log = Logger.getLogger(ContagionDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Fraud Contagion Spread");
        int[][] grid = {
            {2, 1, 1},
            {1, 1, 0},
            {0, 1, 1}
        };
        ContagionSimulator sim = new ContagionSimulator();
        sim.minutesToSpread(grid); // expect 4
    }
}
